Order submit(OrderRequest req) {
    Objects.requireNonNull(req, "req");                 // guard: bad input
    if (req.lines().isEmpty())
        throw new IllegalArgumentException("empty order");
    if (clock.instant().isBefore(req.readyAt()))
        return Order.pending(req);                      // guard: not ready yet
    return processor.run(req);                          // happy path stays flat
}
